import { ChangeDetectionStrategy, Component, computed, signal } from '@angular/core';

@Component({
  selector: 'app-root',
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export class AppComponent {
  readonly minSize = 2;
  readonly maxSize = 20;

  readonly size = signal(8);
  readonly selectedKey = signal<string | null>(null);

  readonly rows = computed(() => Array.from({ length: this.size() }, (_, index) => index));
  readonly selectedLabel = computed(() => {
    const key = this.selectedKey();
    if (!key) return 'Selected: none';
    const [row, col] = key.split('-').map(Number);
    return 'Selected: row ' + String(row + 1) + ', column ' + String(col + 1);
  });

  onSizeInput(raw: string): void {
    const next = Number(raw);
    if (!Number.isFinite(next)) return;
    const clamped = Math.max(this.minSize, Math.min(this.maxSize, Math.trunc(next)));
    this.size.set(clamped);
    this.selectedKey.set(null);
  }

  onCellClick(row: number, col: number): void {
    this.selectedKey.set(this.cellKey(row, col));
  }

  cellKey(row: number, col: number): string {
    return String(row) + '-' + String(col);
  }

  // Per cell, so a method rather than a computed; Angular still tracks the selectedKey() read.
  cellClass(row: number, col: number): string {
    const dark = (row + col) % 2 === 1;
    const active = this.selectedKey() === this.cellKey(row, col);
    return 'cell ' + (dark ? 'cell--dark' : 'cell--light') + (active ? ' cell--active' : '');
  }
}
